// appendTo appends the message's other repeating groups to dst.
func (b *tradingSessionStatus_groups) appendTo(dst []fix.Field) []fix.Field {
	if len(b.noSecurityAltIDEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoSecurityAltID, len(b.noSecurityAltIDEntries))
		for _, entry := range b.noSecurityAltIDEntries {
			dst = entry.appendTo(dst, tradingSessionStatus_NoSecurityAltID_layout)
		}
	}
	if len(b.noEventsEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoEvents, len(b.noEventsEntries))
		for _, entry := range b.noEventsEntries {
			dst = entry.appendTo(dst, tradingSessionStatus_NoEvents_layout)
		}
	}
	if len(b.noInstrumentPartiesEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoInstrumentParties, len(b.noInstrumentPartiesEntries))
		for _, entry := range b.noInstrumentPartiesEntries {
			dst = entry.appendTo(dst, tradingSessionStatus_NoInstrumentParties_layout)
		}
	}
	return dst
}
